def bands(g):
    sep=max(set(v for r in g for v in r), key=lambda c: sum(r.count(c) for r in g))
    H=len(g); W=len(g[0])
    # full separator rows
    frows=[i for i,row in enumerate(g) if all(v==sep for v in row)]
    fcols=[j for j in range(W) if all(g[i][j]==sep for i in range(H))]
    return sep,frows,fcols

