def find_sep(g):
    H,W=len(g),len(g[0])
    for c in range(10):
        fr=[i for i in range(H) if all(g[i][j]==c for j in range(W))]
        fc=[j for j in range(W) if all(g[i][j]==c for i in range(H))]
        if fr and fc: return c,fr,fc
    return None,[],[]

def solve(inp):
    H,W=len(inp),len(inp[0])
    sep,fr,fc=find_sep(inp)
    re=[0]+[i+1 for i in fr]+[H]; ce=[0]+[j+1 for j in fc]+[W]
    bandr=[(re[i],re[i+1]) for i in range(len(re)-1)]
    colb=[(ce[j],ce[j+1]) for j in range(len(ce)-1)]
    # collect shapes per band
    bandshapes={}
    for bi,(r0,r1) in enumerate(bandr):
        for (c0,c1) in colb:
            cells=[(i-r0,j-c0,inp[i][j]) for i in range(r0,r1) for j in range(c0,c1) if inp[i][j]!=0 and inp[i][j]!=sep]
            if cells: bandshapes.setdefault(bi,[]).append((cells,(r0,r1,c0,c1)))
    # template: the shape that is not a 2x2 square (globally unique non-square)
    nonsq=[]
    for bi,sh in bandshapes.items():
        for cells,loc in sh:
            pos={(i,j) for i,j,v in cells}
            if pos!={(0,1),(0,2),(1,1),(1,2)} and pos!={(1,1),(1,2),(2,1),(2,2)}:
                nonsq.append((bi,cells,loc))
    assert len(nonsq)==1, nonsq
    tbi,tcells,tloc=nonsq[0]
    tmpl={(i,j) for i,j,v in tcells}
    tr0=tloc[0]-bandr[tbi][0]  # template row offset within its band
    tc0=tloc[2]-colb[[k for k,(a,b) in enumerate(colb) if a<=tloc[2]<b][0]][0]
    out=[row[:] for row in inp]
    for bi,(r0,r1) in enumerate(bandr):
        sq=[ (cells,loc) for cells,loc in bandshapes.get(bi,[]) if {(i,j) for i,j,v in cells} in ({(0,1),(0,2),(1,1),(1,2)},{(1,1),(1,2),(2,1),(2,2)})]
        if not sq: continue
        color=sq[0][0][0][2]
        br0,br1=r0,r1
        for (c0,c1) in colb:
            for (i,j) in tmpl:
                out[br0+i-tr0 if False else 0][0]=out[0][0]  # noop
        # place template anchored: rows = band rows, offset so template fits
        th=max(i for i,j in tmpl)+1
        # anchor: align template top with band top? demo2 template occupied band-rel rows 0..2; check output
        for (c0,c1) in colb:
            # clear block
            for i in range(br0,br1):
                for j in range(c0,c1):
                    if out[i][j]!=sep: out[i][j]=0
            for (i,j) in tmpl:
                out[br0+i][c0+j]=color
    return out

